## Load up the ISOs:
def load_ISO_file(ISOpath):    
    ISOfile = open(ISOpath+"ListOfISOs.txt","r")
    raw_ISOs = ISOfile.read().rstrip().split("\n")
    list_of_ISOs = [x.split()[1] for x in raw_ISOs]
    return list_of_ISOs



